	// reversed.
	second := buildRegisteredGraph(t, [][]string{
		{"root"},
		{ff, "root"},
		{fe, "root"},
		{"report", ff, fe},
	})

	_, err1 := ExportUpstreamLineage(first, "report")
	_, err2 := ExportUpstreamLineage(second, "report")
