150		// Independent source first, cyclic own-downstream second.
151		err := Register(graph, Dataset{Name: "mid"}, []string{"extra", "leaf"})
152		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "leaf") {
153			t.Fatalf("want cycle error naming leaf, got %v", err)
154		}
