614			t.Fatalf("Impacts(s): %v", err)
615		}
616		assertImpact(t, impacts, "n", 2, []string{"s", "x1", "n"})
617	
618		// A longer-looking but lexicographically smaller route must not replace a
619		// genuinely shorter path: distance takes priority. q joins at distance 2 via
620		// z, and at distance 3 via a -> m.
621		mustRegister(t, graph, "q", "m", "z")
622		impacts, err = Impacts(graph, "s")
623		if err != nil {
624			t.Fatalf("Impacts(s): %v", err)
625		}
626		assertImpact(t, impacts, "q", 2, []string{"s", "z", "q"})
